 {page==='Catálogo'&&<div className="datefilters catalogsort"><label>Ordenar por<select value={sortField} onChange={e=>setSortField(e.target.value)}><option value="model">Modelo</option><option value="type">Tipo de producto</option><option value="brand">Marca</option></select></label><label>Canal del producto<select value={catalogChannel} onChange={e=>setCatalogChannel(e.target.value)}><option value="">Todos los productos</option><option value="P1">P1</option><option value="P3">P3</option></select></label></div>}
 {page!=='Catálogo'&&<div className="datefilters"><label>Desde<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>Hasta<input type="date" min={from} value={to} onChange={e=>setTo(e.target.value)}/></label><label>Canal del producto<select value={channel} onChange={e=>setChannel(e.target.value)}><option value="">P1 y P3</option><option>P1</option><option>P3</option></select></label><button className="textbutton" onClick={clearFilters}>Limpiar filtros</button></div>}
 {page!=='Catálogo'&&<><AdvancedFilters value={{...advanced,from,to}} onChange={updateAdvanced} sellers={sellerChoices} today={today()}/>{from&&to&&from>to&&<p className="filtererror" role="alert">La fecha inicial es posterior a la final. Corrige el período.</p>}</>}
